            hi = int(b) if b else MAX
        else:
            lo = hi = int(item)
        out.append((lo, hi, i))
    return out

def parse_F(Fs):
    hdr = ['h%d' % i for i in range(1, 9)]
    out = []
    for i, name in enumerate(Fs.split()):
        for j, h in enumerate(hdr):
            if h == name:
                out.append((j+1, j+1, i))
    return out

def pointer_assign(ranges, nfields=8):
