    it = 0
    for idx in range(1, nfields+1):
        while True:
            if it < len(ranges):
                lo, hi, pos = ranges[it]
                if idx > hi:
                    it += 1; continue
                if idx >= lo:
                    slots.setdefault(pos, []).append('h%d' % idx)
                break
