strategies = {}
for order in ['fF', 'Ff']:
    for off in ['none', 'F+lenf', 'f+lenF', 'F+lenf_uniq', 'f+lenF_uniq']:
        for sort in ['none', 'sort_lhp', 'sort_lh_stable', 'sort_each', 'sort_each_then_all', 'sort_pos']:
