import itertools
MAX = 10**9
HDR = ['h%d' % i for i in range(1, 9)]
def parse_f(spec):
    if spec == "": return []
    out = []
    for i, item in enumerate(spec.split(',')):
        if '-' in item:
            a, b = item.split('-', 1)
            lo = int(a) if a else 1
            hi = int(b) if b else MAX
        else:
            lo = hi = int(item)
        out.append((lo, hi, i))
    return out

def parse_F(Fs, posmode):
    out = []
    cnt = 0
    for i, name in enumerate(Fs.split()):
        for j, h in enumerate(HDR):
            if h == name:
                pos = {'i': i, 'j': j, 'cnt': cnt}[posmode]
                out.append((j+1, j+1, pos)); cnt += 1
    return out

def owner_map(sorted_ranges, nfields=8):
    # pointer algorithm: returns list of (field_idx, range_index_in_sorted)
    owners = []
    it = 0
    for idx in range(1, nfields+1):
        while True:
            if it < len(sorted_ranges):
                lo, hi, pos = sorted_ranges[it]
                if idx > hi: it += 1; continue
                if idx >= lo: owners.append((idx, it))
                break
            else: break
    return owners

def assign_slots_fieldorder(sorted_ranges):
    slots = {}
    for idx, ri in owner_map(sorted_ranges):
        slots.setdefault(sorted_ranges[ri][2], []).append(idx)
    return ' '.join('h%d' % f for p in sorted(slots) for f in slots[p])

def assign_slots_rangeorder(sorted_ranges, iter_order):
    # iter_order: list of ranges (same tuples) in iteration order; push owned fields per range
    owned = {}
    for idx, ri in owner_map(sorted_ranges):
        owned.setdefault(ri, []).append(idx)
    # map range tuple -> sorted index (tuples may be duplicated; handle by identity via index mapping)
    slots = {}
    used = set()
    for r in iter_order:
        # find sorted index of r not yet used
        for ri, sr in enumerate(sorted_ranges):
            if sr == r and ri not in used:
                used.add(ri); break
        else: continue
        for f in owned.get(ri, []):
            slots.setdefault(r[2], []).append(f)
    return ' '.join('h%d' % f for p in sorted(slots) for f in slots[p])

def output_by_order(sorted_ranges, iter_order):
    owned = {}
    for idx, ri in owner_map(sorted_ranges):
        owned.setdefault(ri, []).append(idx)
    out = []; used = set()
    for r in iter_order:
        for ri, sr in enumerate(sorted_ranges):
            if sr == r and ri not in used:
                used.add(ri); break
        else: continue
        out.extend(owned.get(ri, []))
    return ' '.join('h%d' % f for f in out)

data = []
for line in open('/tmp/data.txt'):
    F, f, out = line.rstrip('\n').split('|')
    data.append((F, f, out))

def offset(r, o): return [(lo, hi, pos+o) for lo, hi, pos in r]

def run(F, f, posmode, off, order, presort, itorder, assign):
    fr = parse_f(f); Fr = parse_F(F, posmode)
    if off == 'f+lenF': fr = offset(fr, len(Fr))
    elif off == 'F+lenf': Fr = offset(Fr, len(fr))
    elif off == 'f+nF': fr = offset(fr, len(F.split()))
    elif off == 'F+1': Fr = offset(Fr, 1)
    elif off == 'f+1': fr = offset(fr, 1)
    if presort == 'each':
        fr = sorted(fr); Fr = sorted(Fr)
    lst = fr + Fr if order == 'fF' else Fr + fr
    srt = sorted(lst, key=lambda r: (r[0], r[1]))  # stable by low, high
    if itorder == 'list': io = lst
    elif itorder == 'sorted': io = srt
    elif itorder == 'pos': io = sorted(lst, key=lambda r: r[2])
    elif itorder == 'pos_from_sorted': io = sorted(srt, key=lambda r: r[2])
    elif itorder == 'poslow': io = sorted(lst, key=lambda r: (r[2], r[0]))
    elif itorder == 'rev': io = list(reversed(lst))
    elif itorder == 'revsorted': io = list(reversed(srt))
    if assign == 'slots_field': return assign_slots_fieldorder(srt)
    if assign == 'slots_range': return assign_slots_rangeorder(srt, io)
    if assign == 'order': return output_by_order(srt, io)

results = []
for posmode in ['i', 'j', 'cnt']:
    for off in ['none', 'f+lenF', 'F+lenf', 'f+nF', 'F+1', 'f+1']:
        for order in ['fF', 'Ff']:
            for presort in ['none', 'each']:
                for itorder in ['list', 'sorted', 'pos', 'pos_from_sorted', 'poslow', 'rev', 'revsorted']:
                    for assign in ['slots_field', 'slots_range', 'order']:
                        ok = 0
                        for F, f, out in data:
                            try:
                                if run(F, f, posmode, off, order, presort, itorder, assign) == out: ok += 1
                            except Exception as e:
                                raise
                        results.append((ok, (posmode, off, order, presort, itorder, assign)))
results.sort(reverse=True)
for r in results[:15]: print(r)
print(len(data))
