MAX = 10**9
def parse_f(spec):
    if spec == "": return []
    out = []
    for i, item in enumerate(spec.split(',')):
        if '-' in item:
            a, b = item.split('-', 1)
            lo = int(a) if a else 1
            hi = int(b) if b else MAX
        else:
            lo = hi = int(item)
        out.append([lo, hi, i, 'f'])
    return out

def parse_F(Fs, nh):
    hdr = ['h%d' % i for i in range(1, nh+1)]
    out = []
    for i, name in enumerate(Fs.split()):
        for j, h in enumerate(hdr):
            if h == name:
                out.append([j+1, j+1, i, 'F'])
    return out

def pointer_slots(ranges, nfields):
    slots = {}
    it = 0
    for idx in range(1, nfields+1):
        while True:
            if it < len(ranges):
                lo, hi, pos = ranges[it][0], ranges[it][1], ranges[it][2]
                if idx > hi: it += 1; continue
                if idx >= lo: slots.setdefault(pos, []).append(idx)
                break
            else: break
    return ' '.join('h%d' % f for p in sorted(slots) for f in slots[p])

