//! Parsing and manipulation of field selections.

use regex::bytes::Regex;
use std::cmp::Ordering;

/// A contiguous, inclusive, zero based range of fields together with the
/// output slot (`pos`) the fields of the range are written to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FieldRange {
    pub low: usize,
    pub high: usize,
    pub pos: usize,
}

impl Ord for FieldRange {
    fn cmp(&self, other: &Self) -> Ordering {
        (self.low, self.high, self.pos).cmp(&(other.low, other.high, other.pos))
    }
}

impl PartialOrd for FieldRange {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

/// Errors produced while parsing a list of fields.
#[derive(Debug)]
pub enum FieldError {
    Parse(String),
    NumberedFromOne(usize),
    HighLessThanLow(usize, usize),
    NoHeadersMatched,
}

impl std::fmt::Display for FieldError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            FieldError::Parse(s) => write!(f, "Failed to parse field: {}", s),
            FieldError::NumberedFromOne(n) => {
                write!(f, "Fields and positions are numbered from 1: {}", n)
            }
            FieldError::HighLessThanLow(l, h) => write!(
                f,
                "High end of range less than low end of range: {}-{}",
                l, h
            ),
            FieldError::NoHeadersMatched => write!(f, "No headers matched"),
        }
    }
}

impl std::error::Error for FieldError {}

/// Maximum number of adjacent merges performed on a single list of ranges.
const MERGE_BUDGET: usize = 2;

impl FieldRange {
    /// Parse a comma separated list of 1-based field specifications.
    pub fn from_list(list: &str) -> Result<Vec<FieldRange>, FieldError> {
        let mut ranges = Vec::new();
        for (pos, item) in list.split(',').enumerate() {
            let mut parts = item.splitn(2, '-');
            let range = match (parts.next(), parts.next()) {
                (Some(nm), None) => {
                    let nm: usize = nm
                        .parse()
                        .map_err(|_| FieldError::Parse(nm.to_string()))?;
                    if nm == 0 {
                        return Err(FieldError::NumberedFromOne(nm));
                    }
                    FieldRange { low: nm - 1, high: nm - 1, pos }
                }
