    pub fn num_slots(ranges: &[FieldRange]) -> usize {
        ranges.iter().map(|r| r.pos + 1).max().unwrap_or(0)
    }

    /// Whether any range selects the very first field.
    pub fn selects_first_field(ranges: &[FieldRange]) -> bool {
