//! Interpretation of a small set of escape sequences in user supplied
//! strings (`\n`, `\r`, `\t`, `\0`, `\\` and `\xHH`). Anything else is kept
//! verbatim, including the backslash.

enum State {
    Literal,
    Escape,
    HexFirst,
    HexSecond(char),
}

pub fn unescape(s: &str) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len());
    let mut state = State::Literal;
    for c in s.chars() {
        state = match state {
            State::Literal => {
                if c == '\\' {
                    State::Escape
                } else {
                    push_char(&mut out, c);
                    State::Literal
                }
            }
            State::Escape => match c {
                '\\' => {
                    out.push(b'\\');
                    State::Literal
                }
                'n' => {
                    out.push(b'\n');
                    State::Literal
                }
                'r' => {
                    out.push(b'\r');
                    State::Literal
                }
                't' => {
                    out.push(b'\t');
                    State::Literal
                }
                '0' => {
                    out.push(0);
                    State::Literal
                }
                'x' => State::HexFirst,
                other => {
                    out.push(b'\\');
                    push_char(&mut out, other);
                    State::Literal
                }
            },
            State::HexFirst => {
                if c.is_ascii_hexdigit() {
                    State::HexSecond(c)
                } else {
                    out.extend_from_slice(b"\\x");
                    push_char(&mut out, c);
                    State::Literal
                }
            }
            State::HexSecond(first) => {
                if c.is_ascii_hexdigit() {
                    let hi = first.to_digit(16).unwrap() as u8;
                    let lo = c.to_digit(16).unwrap() as u8;
                    out.push(hi * 16 + lo);
                } else {
                    out.extend_from_slice(b"\\x");
                    push_char(&mut out, first);
                    push_char(&mut out, c);
                }
                State::Literal
            }
        };
    }
    match state {
        State::Literal => {}
        State::Escape => out.push(b'\\'),
        State::HexFirst => out.extend_from_slice(b"\\x"),
        State::HexSecond(first) => {
            out.extend_from_slice(b"\\x");
            push_char(&mut out, first);
        }
    }
    out
}

fn push_char(out: &mut Vec<u8>, c: char) {
    let mut buf = [0u8; 4];
    out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
}
