//! Diagnostics: a tiny `RUST_LOG` aware logger that mimics the default
//! `env_logger` output format, plus helpers to report fatal conditions in the
//! same shape as a Rust panic.

use std::io::Write;
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Level {
    Off = 0,
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

impl Level {
    fn parse(s: &str) -> Option<Level> {
        match s.to_ascii_lowercase().as_str() {
            "off" | "0" => Some(Level::Off),
            "error" | "1" => Some(Level::Error),
            "warn" | "2" => Some(Level::Warn),
            "info" | "3" => Some(Level::Info),
            "debug" | "4" => Some(Level::Debug),
            "trace" | "5" => Some(Level::Trace),
            _ => None,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Level::Off => "OFF",
            Level::Error => "ERROR",
            Level::Warn => "WARN",
            Level::Info => "INFO",
            Level::Debug => "DEBUG",
            Level::Trace => "TRACE",
        }
    }
}

const TARGET: &str = "hck";

/// Determine the maximum level enabled for our target from `RUST_LOG`.
fn enabled_level() -> Level {
    let spec = match std::env::var("RUST_LOG") {
        Ok(s) => s,
        Err(_) => return Level::Info,
    };
    let mut global: Option<Level> = None;
    let mut best: Option<(usize, Level)> = None;
    let mut any = false;
    for directive in spec.split(',') {
        let directive = directive.split('/').next().unwrap_or("");
        let directive = directive.trim();
        if directive.is_empty() {
            continue;
        }
        any = true;
        match directive.split_once('=') {
            Some((name, level)) => {
                let level = Level::parse(level.trim()).unwrap_or(Level::Trace);
                let name = name.trim();
                if name.is_empty() {
                    global = Some(level);
                } else if TARGET == name || TARGET.starts_with(&format!("{}::", name)) {
                    if best.map(|(n, _)| name.len() >= n).unwrap_or(true) {
                        best = Some((name.len(), level));
                    }
                }
            }
            None => {
                if let Some(level) = Level::parse(directive) {
                    global = Some(level);
                } else if TARGET == directive
                    || TARGET.starts_with(&format!("{}::", directive))
                {
                    if best.map(|(n, _)| directive.len() >= n).unwrap_or(true) {
                        best = Some((directive.len(), Level::Trace));
                    }
                }
            }
        }
    }
    if !any {
        return Level::Error;
    }
    if let Some((_, l)) = best {
        return l;
    }
    global.unwrap_or(Level::Off)
}

fn timestamp() -> String {
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let days = secs.div_euclid(86_400);
    let rem = secs.rem_euclid(86_400);
    let (h, m, s) = (rem / 3600, (rem % 3600) / 60, rem % 60);
    // civil-from-days (Howard Hinnant's algorithm)
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let mo = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if mo <= 2 { y + 1 } else { y };
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z", y, mo, d, h, m, s)
}

fn log(level: Level, msg: &str) {
    if level > enabled_level() {
        return;
    }
    let mut out = String::new();
    out.push_str(&format!("[{} {:<5} {}] ", timestamp(), level.label(), TARGET));
    let mut first = true;
    for line in msg.split('\n') {
        if !first {
            out.push_str("\n    ");
        }
        out.push_str(line);
        first = false;
    }
    out.push('\n');
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
}

pub fn error(msg: &str) {
    log(Level::Error, msg);
}

pub fn warn(msg: &str) {
    log(Level::Warn, msg);
}

/// Print a message in the shape of a Rust panic message and return the
/// matching process exit code (101).
pub fn panic_message(location: &str, msg: &str) {
    let mut out = format!("\nthread 'main' panicked at {}:\n{}\n", location, msg);
    let backtrace = std::env::var("RUST_BACKTRACE")
        .map(|v| v != "0" && !v.is_empty())
        .unwrap_or(false);
    if backtrace {
        out.push_str("stack backtrace:\nnote: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.\n");
    } else {
        out.push_str(
            "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        );
    }
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
}

pub const PANIC_EXIT_CODE: i32 = 101;
