/// Raw DEFLATE compressor. Prefers the system `libdeflate` library when it can
/// be loaded at runtime, otherwise falls back to the pure Rust implementation.
pub enum Deflater {
    LibDeflate(LibDeflate),
    Rust(u32),
}

type AllocFn = unsafe extern "C" fn(c_int) -> *mut c_void;
type BoundFn = unsafe extern "C" fn(*mut c_void, usize) -> usize;
type CompressFn = unsafe extern "C" fn(*mut c_void, *const u8, usize, *mut u8, usize) -> usize;

pub struct LibDeflate {
    compressor: *mut c_void,
    bound: BoundFn,
    compress: CompressFn,
}

extern "C" {
    fn dlopen(filename: *const c_char, flag: c_int) -> *mut c_void;
    fn dlsym(handle: *mut c_void, symbol: *const c_char) -> *mut c_void;
}

const RTLD_NOW: c_int = 2;

impl LibDeflate {
    fn open(level: u32) -> Option<LibDeflate> {
        unsafe {
            let mut handle = std::ptr::null_mut();
            for name in ["libdeflate.so.0", "libdeflate.so"] {
                let cname = CString::new(name).ok()?;
                handle = dlopen(cname.as_ptr(), RTLD_NOW);
                if !handle.is_null() {
                    break;
                }
            }
            if handle.is_null() {
                return None;
            }
            let sym = |n: &str| -> Option<*mut c_void> {
                let c = CString::new(n).ok()?;
                let p = dlsym(handle, c.as_ptr());
                if p.is_null() {
                    None
                } else {
                    Some(p)
                }
            };
            let alloc: AllocFn = std::mem::transmute(sym("libdeflate_alloc_compressor")?);
            let bound: BoundFn = std::mem::transmute(sym("libdeflate_deflate_compress_bound")?);
            let compress: CompressFn = std::mem::transmute(sym("libdeflate_deflate_compress")?);
            let compressor = alloc(level.min(12) as c_int);
            if compressor.is_null() {
                return None;
            }
            Some(LibDeflate { compressor, bound, compress })
        }
    }

    fn compress(&self, input: &[u8], out: &mut Vec<u8>) -> bool {
        unsafe {
            let bound = (self.bound)(self.compressor, input.len());
            out.clear();
            out.reserve(bound);
            let n = (self.compress)(
                self.compressor,
                input.as_ptr(),
                input.len(),
                out.as_mut_ptr(),
                bound,
            );
            if n == 0 {
                return false;
            }
            out.set_len(n);
            true
        }
    }
}

impl Deflater {
    pub fn new(level: u32) -> Deflater {
        match LibDeflate::open(level) {
            Some(l) => Deflater::LibDeflate(l),
            None => Deflater::Rust(level.min(10)),
        }
    }

    fn compress(&self, input: &[u8], out: &mut Vec<u8>) {
        if let Deflater::LibDeflate(l) = self {
            if l.compress(input, out) {
                return;
            }
        }
        let level = match self {
            Deflater::Rust(l) => *l,
            Deflater::LibDeflate(_) => 6,
        };
        out.clear();
        let mut c = flate2::Compress::new(flate2::Compression::new(level), false);
        let mut buf = Vec::with_capacity(input.len() + input.len() / 8 + 64);
        loop {
            match c.compress_vec(&input[c.total_in() as usize..], &mut buf, flate2::FlushCompress::Finish) {
                Ok(flate2::Status::StreamEnd) => break,
                Ok(_) => {
                    if buf.len() == buf.capacity() {
                        buf.reserve(buf.capacity());
                    }
                }
                Err(_) => break,
            }
        }
        *out = buf;
    }
}

/// A writer producing BGZF (blocked gzip) output.
pub struct BgzfWriter<W: Write> {
    inner: Option<W>,
    buffer: Vec<u8>,
    compressed: Vec<u8>,
    deflater: Deflater,
    level: u32,
    blocks_written: usize,
    finished: bool,
}

impl<W: Write> BgzfWriter<W> {
    pub fn new(inner: W, level: u32) -> BgzfWriter<W> {
        BgzfWriter {
            inner: Some(inner),
            buffer: Vec::with_capacity(BGZF_BLOCK_SIZE * 2),
            compressed: Vec::new(),
            deflater: Deflater::new(level),
            level,
            blocks_written: 0,
            finished: false,
        }
    }

    fn write_block(&mut self, data: &[u8]) -> io::Result<()> {
        let mut compressed = std::mem::take(&mut self.compressed);
        self.deflater.compress(data, &mut compressed);
        let mut crc = flate2::Crc::new();
        crc.update(data);
        let xfl: u8 = if self.level >= 9 {
            2
        } else if self.level <= 1 {
            4
        } else {
            0
        };
        let total = 18 + compressed.len() + 8;
        let bsize = (total - 1) as u16;
        let mut header = [
            0x1f, 0x8b, 0x08, 0x04, 0x00, 0x00, 0x00, 0x00, xfl, 0xff, 0x06, 0x00, 0x42, 0x43, 0x02,
            0x00, 0x00, 0x00,
        ];
        header[16..18].copy_from_slice(&bsize.to_le_bytes());
        let inner = self.inner.as_mut().expect("writer finished");
        inner.write_all(&header)?;
        inner.write_all(&compressed)?;
        inner.write_all(&crc.sum().to_le_bytes())?;
        inner.write_all(&(data.len() as u32).to_le_bytes())?;
        self.blocks_written += 1;
        self.compressed = compressed;
        Ok(())
    }

    fn flush_blocks(&mut self) -> io::Result<()> {
        let mut start = 0;
        while self.buffer.len() - start >= BGZF_BLOCK_SIZE {
            let block = self.buffer[start..start + BGZF_BLOCK_SIZE].to_vec();
            self.write_block(&block)?;
            start += BGZF_BLOCK_SIZE;
        }
        if start > 0 {
            self.buffer.drain(..start);
        }
        Ok(())
    }

    /// Compress any remaining data, write the end-of-file marker and flush.
    pub fn finish(&mut self) -> io::Result<()> {
        if self.finished {
            return Ok(());
        }
        self.finished = true;
        self.flush_blocks()?;
        if !self.buffer.is_empty() || self.blocks_written == 0 {
            let block = std::mem::take(&mut self.buffer);
            self.write_block(&block)?;
        }
        let inner = self.inner.as_mut().expect("writer finished");
        inner.write_all(&BGZF_EOF)?;
        inner.flush()
    }
}

impl<W: Write> Write for BgzfWriter<W> {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        self.buffer.extend_from_slice(buf);
        if self.buffer.len() >= BGZF_BLOCK_SIZE {
            self.flush_blocks()?;
        }
        Ok(buf.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

impl<W: Write> Drop for BgzfWriter<W> {
    fn drop(&mut self) {
        let _ = self.finish();
    }
}
