//! Opening of inputs, including transparent decompression.

use std::ffi::OsStr;
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::thread::JoinHandle;

/// Where input comes from.
#[derive(Clone, Debug)]
pub enum Input {
    Stdin,
    Path(String),
}

impl Input {
    pub fn from_arg(arg: &str) -> Input {
        if arg == "-" {
            Input::Stdin
        } else {
            Input::Path(arg.to_string())
        }
    }

    pub fn is_stdin(&self) -> bool {
        matches!(self, Input::Stdin)
    }
}

/// External decompression programs keyed by file name suffix.
const DECOMPRESSORS: &[(&str, &[&str])] = &[
    (".tgz", &["gzip", "-d", "-c"]),
    (".bz2", &["bzip2", "-d", "-c"]),
    (".tbz2", &["bzip2", "-d", "-c"]),
    (".xz", &["xz", "-d", "-c"]),
    (".txz", &["xz", "-d", "-c"]),
    (".lz4", &["lz4", "-d", "-c"]),
    (".lzma", &["xz", "--format=lzma", "-d", "-c"]),
    (".br", &["brotli", "-d", "-c"]),
    (".zst", &["zstd", "-q", "-d", "-c"]),
    (".zstd", &["zstd", "-q", "-d", "-c"]),
    (".Z", &["uncompress", "-c"]),
];

fn has_suffix(path: &str, suffix: &str) -> bool {
    path.len() > suffix.len() && path.ends_with(suffix)
}

/// Locate an executable in `PATH`.
fn resolve_binary(name: &str) -> Option<PathBuf> {
    let path = std::env::var_os("PATH")?;
    for dir in std::env::split_paths(&path) {
        if dir.as_os_str().is_empty() {
            continue;
        }
        let candidate = dir.join(name);
        if let Ok(meta) = std::fs::metadata(&candidate) {
            if meta.is_file() {
                use std::os::unix::fs::PermissionsExt;
                if meta.permissions().mode() & 0o111 != 0 {
                    return Some(candidate);
                }
            }
        }
    }
    None
}

/// A reader over the stdout of a child process. When the child exits
/// unsuccessfully, its stderr is reported as an error.
pub struct CommandReader {
    child: Child,
    stdout: std::process::ChildStdout,
    stderr: Option<JoinHandle<Vec<u8>>>,
    done: bool,
