//! Splitting lines into fields and writing the selected fields back out.

use crate::field_range::FieldRange;
use regex::bytes::Regex;
use std::io::{self, Write};

/// Source location reported when the single byte parser trips over a line
/// that starts with the delimiter while the first field is selected.
pub const SINGLE_BYTE_PANIC_LOCATION: &str = "/workspace/src/lib/single_byte_delim_parser.rs:84:57";
pub const SINGLE_BYTE_PANIC_MESSAGE: &str = "attempted to index slice up to maximum usize";

/// Errors raised while processing data.
pub enum ProcessError {
    Io(io::Error),
    /// A fatal internal condition reported in the shape of a panic.
    Panic(&'static str, String),
}

impl From<io::Error> for ProcessError {
    fn from(e: io::Error) -> Self {
        ProcessError::Io(e)
    }
}

/// How input lines are split into fields.
pub enum Delimiter {
    Regex(Regex),
    Literal(Vec<u8>),
    Byte(u8),
}

impl Delimiter {
    pub fn literal(bytes: Vec<u8>) -> Delimiter {
        if bytes.len() == 1 {
            Delimiter::Byte(bytes[0])
        } else {
            Delimiter::Literal(bytes)
        }
    }

    /// Split `line` into fields, calling `f` with the (start, end) offsets of
    /// each field. Returns early when `f` returns `false`.
    fn for_each_field<F: FnMut(usize, usize) -> bool>(&self, line: &[u8], mut f: F) {
        let mut last = 0;
        match self {
            Delimiter::Regex(re) => {
                for m in re.find_iter(line) {
                    if !f(last, m.start()) {
                        return;
                    }
                    last = m.end();
                }
            }
            Delimiter::Literal(needle) => {
                for pos in memchr::memmem::find_iter(line, needle) {
                    if !f(last, pos) {
                        return;
                    }
                    last = pos + needle.len();
                }
            }
            Delimiter::Byte(b) => {
                for pos in memchr::memchr_iter(*b, line) {
                    if !f(last, pos) {
                        return;
                    }
                    last = pos + 1;
                }
            }
        }
        f(last, line.len());
    }

    /// Split a line into owned field slices.
    pub fn split<'a>(&self, line: &'a [u8]) -> Vec<&'a [u8]> {
        let mut out = Vec::new();
        self.for_each_field(line, |s, e| {
            out.push(&line[s..e]);
            true
        });
        out
    }
}

/// The field selecting and reordering engine.
pub struct Core {
    ranges: Vec<FieldRange>,
    slots: Vec<Vec<(usize, usize)>>,
    delim: Delimiter,
    out_delim: Vec<u8>,
    crlf: bool,
    selects_first: bool,
}

impl Core {
    pub fn new(ranges: Vec<FieldRange>, delim: Delimiter, out_delim: Vec<u8>, crlf: bool) -> Core {
        let nslots = FieldRange::num_slots(&ranges);
        let selects_first = FieldRange::selects_first_field(&ranges);
        Core {
            ranges,
            slots: vec![Vec::new(); nslots],
            delim,
            out_delim,
            crlf,
            selects_first,
        }
    }

    pub fn is_single_byte(&self) -> bool {
        matches!(self.delim, Delimiter::Byte(_))
    }

    pub fn line_ending(&self) -> &'static [u8] {
        if self.crlf {
            b"\r\n"
        } else {
            b"\n"
        }
    }

    /// Strip the line terminator (and carriage return when in CRLF mode).
    fn trim_line<'a>(&self, mut line: &'a [u8]) -> &'a [u8] {
        if let [rest @ .., b'\n'] = line {
            line = rest;
        }
        if self.crlf {
            if let [rest @ .., b'\r'] = line {
                line = rest;
            }
        }
        line
    }

    /// Select the fields of a single (terminator free) line and write them.
    pub fn write_line<W: Write + ?Sized>(&mut self, line: &[u8], out: &mut W) -> io::Result<()> {
        for slot in self.slots.iter_mut() {
            slot.clear();
        }
        let ranges = &self.ranges;
        let slots = &mut self.slots;
        let mut it = 0usize;
        let mut idx = 0usize;
        self.delim.for_each_field(line, |s, e| {
            while it < ranges.len() && idx > ranges[it].high {
                it += 1;
            }
            if it == ranges.len() {
                return false;
            }
            if idx >= ranges[it].low {
                slots[ranges[it].pos].push((s, e));
            }
            idx += 1;
            true
        });
        let mut first = true;
        for slot in self.slots.iter() {
            for &(s, e) in slot {
                if !first {
                    out.write_all(&self.out_delim)?;
                }
                out.write_all(&line[s..e])?;
                first = false;
            }
        }
        out.write_all(self.line_ending())
    }

    /// Process a buffer of complete lines (the buffer ends with a newline).
    pub fn process_chunk<W: Write + ?Sized>(&mut self, buf: &[u8], out: &mut W) -> Result<(), ProcessError> {
        let mut start = 0;
        for nl in memchr::memchr_iter(b'\n', buf) {
            let raw = &buf[start..=nl];
            if start == 0 && self.selects_first {
                if let Delimiter::Byte(b) = self.delim {
                    if raw.first() == Some(&b) {
                        return Err(ProcessError::Panic(
                            SINGLE_BYTE_PANIC_LOCATION,
                            SINGLE_BYTE_PANIC_MESSAGE.to_string(),
                        ));
                    }
                }
            }
            let line = self.trim_line(raw);
            self.write_line(line, out)?;
            start = nl + 1;
        }
        Ok(())
    }

    /// Process trailing data that is not terminated by a newline.
    pub fn process_tail<W: Write + ?Sized>(&mut self, buf: &[u8], out: &mut W) -> Result<(), ProcessError> {
        if buf.is_empty() {
            return Ok(());
        }
        if self.is_single_byte() {
            return Err(ProcessError::Io(io::Error::from(io::ErrorKind::InvalidData)));
        }
        let line = self.trim_line(buf);
        self.write_line(line, out)?;
        Ok(())
    }
}

/// Default read size for streamed input.
pub const CHUNK_SIZE: usize = 64 * 1024;

/// Feed a stream through the core, chunk by chunk.
pub fn process_stream<R: io::Read + ?Sized, W: Write + ?Sized>(
    reader: &mut R,
    core: &mut Core,
    out: &mut W,
) -> Result<(), ProcessError> {
    let mut buf = vec![0u8; CHUNK_SIZE];
    let mut len = 0usize;
    loop {
        if len == buf.len() {
            let new_len = buf.len() * 2;
            buf.resize(new_len, 0);
        }
        let n = match reader.read(&mut buf[len..]) {
            Ok(n) => n,
            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(ProcessError::Io(e)),
        };
        if n == 0 {
            return core.process_tail(&buf[..len], out);
        }
        len += n;
        if let Some(nl) = memchr::memrchr(b'\n', &buf[..len]) {
            core.process_chunk(&buf[..=nl], out)?;
            let rest = len - (nl + 1);
            buf.copy_within(nl + 1..len, 0);
            len = rest;
        }
    }
}

/// Process a buffer holding the entire input.
pub fn process_whole<W: Write + ?Sized>(data: &[u8], core: &mut Core, out: &mut W) -> Result<(), ProcessError> {
    match memchr::memrchr(b'\n', data) {
        Some(nl) => {
            core.process_chunk(&data[..=nl], out)?;
            core.process_tail(&data[nl + 1..], out)
        }
        None => core.process_tail(data, out),
    }
}
