            if let [rest @ .., b'\r'] = line {
                line = rest;
            }
        }
        line
    }

    /// Select the fields of a single (terminator free) line and write them.
    pub fn write_line<W: Write + ?Sized>(&mut self, line: &[u8], out: &mut W) -> io::Result<()> {
        for slot in self.slots.iter_mut() {
            slot.clear();
        }
        let ranges = &self.ranges;
        let slots = &mut self.slots;
        let mut it = 0usize;
        let mut idx = 0usize;
        self.delim.for_each_field(line, |s, e| {
            while it < ranges.len() && idx > ranges[it].high {
                it += 1;
            }
            if it == ranges.len() {
                return false;
            }
            if idx >= ranges[it].low {
                slots[ranges[it].pos].push((s, e));
            }
            idx += 1;
            true
        });
        let mut first = true;
        for slot in self.slots.iter() {
            for &(s, e) in slot {
                if !first {
                    out.write_all(&self.out_delim)?;
                }
                out.write_all(&line[s..e])?;
                first = false;
            }
        }
        out.write_all(self.line_ending())
    }

    /// Process a buffer of complete lines (the buffer ends with a newline).
    pub fn process_chunk<W: Write + ?Sized>(&mut self, buf: &[u8], out: &mut W) -> Result<(), ProcessError> {
        let mut start = 0;
        for nl in memchr::memchr_iter(b'\n', buf) {
            let raw = &buf[start..=nl];
            if start == 0 && self.selects_first {
                if let Delimiter::Byte(b) = self.delim {
                    if raw.first() == Some(&b) {
                        return Err(ProcessError::Panic(
                            SINGLE_BYTE_PANIC_LOCATION,
                            SINGLE_BYTE_PANIC_MESSAGE.to_string(),
                        ));
                    }
                }
            }
            let line = self.trim_line(raw);
            self.write_line(line, out)?;
            start = nl + 1;
        }
        Ok(())
    }

    /// Process trailing data that is not terminated by a newline.
    pub fn process_tail<W: Write + ?Sized>(&mut self, buf: &[u8], out: &mut W) -> Result<(), ProcessError> {
        if buf.is_empty() {
            return Ok(());
        }
        if self.is_single_byte() {
            return Err(ProcessError::Io(io::Error::from(io::ErrorKind::InvalidData)));
        }
        let line = self.trim_line(buf);
        self.write_line(line, out)?;
        Ok(())
    }
}

/// Default read size for streamed input.
pub const CHUNK_SIZE: usize = 64 * 1024;

/// Feed a stream through the core, chunk by chunk.
pub fn process_stream<R: io::Read + ?Sized, W: Write + ?Sized>(
    reader: &mut R,
    core: &mut Core,
    out: &mut W,
) -> Result<(), ProcessError> {
    let mut buf = vec![0u8; CHUNK_SIZE];
    let mut len = 0usize;
    loop {
        if len == buf.len() {
            let new_len = buf.len() * 2;
            buf.resize(new_len, 0);
        }
        let n = match reader.read(&mut buf[len..]) {
            Ok(n) => n,
            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(ProcessError::Io(e)),
        };
        if n == 0 {
            return core.process_tail(&buf[..len], out);
        }
        len += n;
        if let Some(nl) = memchr::memrchr(b'\n', &buf[..len]) {
            core.process_chunk(&buf[..=nl], out)?;
            let rest = len - (nl + 1);
            buf.copy_within(nl + 1..len, 0);
            len = rest;
        }
    }
}

/// Process a buffer holding the entire input.
pub fn process_whole<W: Write + ?Sized>(data: &[u8], core: &mut Core, out: &mut W) -> Result<(), ProcessError> {
    match memchr::memrchr(b'\n', data) {
        Some(nl) => {
            core.process_chunk(&data[..=nl], out)?;
            core.process_tail(&data[nl + 1..], out)
        }
        None => core.process_tail(data, out),
    }
}
