/// Fatal conditions.
enum Fatal {
    /// Logged as an error, exit code 1, buffered output discarded.
    Logged(String),
    /// Reported like a panic, exit code 101, buffered output flushed.
    Panic(&'static str, String),
    /// A broken pipe on output: silently exit with success.
    BrokenPipe,
}

impl From<io::Error> for Fatal {
    fn from(e: io::Error) -> Fatal {
        if e.kind() == io::ErrorKind::BrokenPipe {
            Fatal::BrokenPipe
        } else {
            Fatal::Logged(e.to_string())
        }
    }
}

impl From<ProcessError> for Fatal {
    fn from(e: ProcessError) -> Fatal {
        match e {
            ProcessError::Io(e) => e.into(),
            ProcessError::Panic(loc, msg) => Fatal::Panic(loc, msg),
        }
    }
}

impl From<FieldError> for Fatal {
    fn from(e: FieldError) -> Fatal {
        Fatal::Logged(e.to_string())
    }
}

type Sink = BufWriter<BufWriter<Box<dyn Write>>>;

fn open_output(opts: &Opts) -> Result<Sink, String> {
    let raw: Box<dyn Write> = match &opts.output {
        Some(path) if path != "-" => match File::create(path) {
            Ok(f) => Box::new(f),
            Err(e) => {
                return Err(format!(
                    "Error: Failed to open {} for writing.\n\nCaused by:\n    {}\n",
                    path, e
                ))
            }
        },
        _ => Box::new(io::stdout()),
    };
    let sink: Box<dyn Write> = if opts.try_compress {
        Box::new(output::BgzfWriter::new(raw, opts.compression_level))
    } else {
        raw
    };
    Ok(BufWriter::with_capacity(8192, BufWriter::with_capacity(8192, sink)))
}

/// The static (header independent) part of the field selection.
struct Selection {
    fields: Option<Vec<FieldRange>>,
    excludes: Vec<FieldRange>,
}

impl Selection {
    /// Ranges to use when no header based selection applies.
    fn plain_ranges(&self) -> Vec<FieldRange> {
        let base = match &self.fields {
            Some(f) => f.clone(),
            None => vec![FieldRange { low: 0, high: usize::MAX - 1, pos: 0 }],
        };
        FieldRange::exclude(base, &self.excludes)
    }

    /// Ranges for a specific header line.
    fn header_ranges(&self, opts: &Opts, header: &[u8], delim: &Delimiter) -> Result<Vec<FieldRange>, FieldError> {
        let header_fields = delim.split(header);
        let mut selected = self.fields.clone().unwrap_or_default();
        if !opts.header_field.is_empty() {
            let by_header = FieldRange::from_header_list(&opts.header_field, &header_fields, opts.header_is_regex);
            if by_header.is_empty() {
                return Err(FieldError::NoHeadersMatched);
            }
            selected = FieldRange::combine(selected, by_header);
        } else if self.fields.is_none() {
            selected = vec![FieldRange { low: 0, high: usize::MAX - 1, pos: 0 }];
        }
        let mut excludes = self.excludes.clone();
        if !opts.exclude_header.is_empty() {
            excludes.extend(FieldRange::from_header_list(
                &opts.exclude_header,
                &header_fields,
                opts.header_is_regex,
            ));
        }
        Ok(FieldRange::exclude(selected, &excludes))
    }
}

fn build_delimiter(opts: &Opts) -> Result<Delimiter, String> {
    if opts.delim_is_literal {
        Ok(Delimiter::literal(unescape::unescape(&opts.delimiter)))
    } else {
        match Regex::new(&opts.delimiter) {
            Ok(re) => Ok(Delimiter::Regex(re)),
            Err(e) => Err(format!("Error: {}\n", e)),
        }
    }
}

fn output_delimiter(opts: &Opts) -> Vec<u8> {
    if opts.delim_is_literal && opts.use_input_delim {
        unescape::unescape(&opts.delimiter)
    } else {
        unescape::unescape(&opts.output_delimiter)
    }
}

/// Read a single line (including its terminator, if any) from a stream.
fn read_header_line<R: Read>(reader: &mut R) -> io::Result<Vec<u8>> {
    let mut buf = Vec::new();
    let mut byte = [0u8; 1];
    loop {
        let n = reader.read(&mut byte)?;
        if n == 0 {
            break;
        }
        buf.push(byte[0]);
        if byte[0] == b'\n' {
            break;
        }
    }
    Ok(buf)
}

fn strip_line_end(mut line: &[u8], crlf: bool) -> &[u8] {
    if let [rest @ .., b'\n'] = line {
        line = rest;
    }
    if crlf {
        if let [rest @ .., b'\r'] = line {
            line = rest;
        }
    }
    line
}

fn process_input(opts: &Opts, selection: &Selection, input: &Input, out: &mut Sink) -> Result<(), Fatal> {
    let delim = build_delimiter(opts).map_err(Fatal::Logged)?;
    let out_delim = output_delimiter(opts);
    let allow_whole = !opts.no_mmap && !opts.try_decompress;

    if !opts.header_mode() {
        let ranges = selection.plain_ranges();
        if ranges.is_empty() {
            return Ok(());
        }
        let mut core = Core::new(ranges, delim, out_delim, opts.crlf);
        return match input::open(input, opts.try_decompress, allow_whole)? {
            Opened::Whole(data) => Ok(process_whole(&data, &mut core, out)?),
            Opened::Stream(mut reader) => Ok(process_stream(&mut *reader, &mut core, out)?),
        };
    }

    if input.is_stdin() {
        if opts.try_decompress {
            if !opts.header_field.is_empty() {
                diag::warn(HEADER_STDIN_WARNING);
            }
            return Err(Fatal::Panic(HEADER_STDIN_PANIC_LOCATION, HEADER_STDIN_PANIC_MESSAGE.to_string()));
        }
        let mut reader = match input::open(input, false, false)? {
            Opened::Stream(r) => r,
            Opened::Whole(_) => unreachable!(),
        };
        let header_line = read_header_line(&mut reader)?;
        let header = strip_line_end(&header_line, opts.crlf);
        let ranges = selection.header_ranges(opts, header, &delim)?;
        if ranges.is_empty() {
            return Ok(());
        }
        let mut core = Core::new(ranges, delim, out_delim, opts.crlf);
        core.write_line(header, out)?;
        process_stream(&mut *reader, &mut core, out)?;
        return Ok(());
    }

    // Files: the header is read through a separate handle, then the whole
    // input (header included) is processed.
    let header_line = match input::open(input, opts.try_decompress, false)? {
        Opened::Stream(mut r) => {
            let mut br = BufReader::new(&mut *r);
            let mut line = Vec::new();
            br.read_until(b'\n', &mut line)?;
            line
        }
        Opened::Whole(data) => {
            let end = memchr::memchr(b'\n', &data).map(|i| i + 1).unwrap_or(data.len());
            data[..end].to_vec()
        }
    };
    let header = strip_line_end(&header_line, opts.crlf);
    let ranges = selection.header_ranges(opts, header, &delim)?;
    if ranges.is_empty() {
        return Ok(());
    }
    let mut core = Core::new(ranges, delim, out_delim, opts.crlf);
    match input::open(input, opts.try_decompress, allow_whole)? {
        Opened::Whole(data) => process_whole(&data, &mut core, out)?,
        Opened::Stream(mut reader) => process_stream(&mut *reader, &mut core, out)?,
    }
    Ok(())
}

fn run(opts: &Opts, out: &mut Sink) -> Result<(), Fatal> {
    // validate the delimiter early
    build_delimiter(opts).map_err(Fatal::Logged)?;
    let fields = match &opts.fields {
        Some(f) => Some(FieldRange::from_list(f)?),
        None => None,
    };
    let excludes = match &opts.exclude {
        Some(e) => FieldRange::from_list(e)?,
        None => Vec::new(),
    };
    let selection = Selection { fields, excludes };

    if !opts.header_mode() && selection.plain_ranges().is_empty() {
        return Ok(());
    }

    let inputs: Vec<Input> = if opts.inputs.is_empty() {
        vec![Input::Stdin]
    } else {
        opts.inputs.clone()
    };
    for input in &inputs {
        process_input(opts, &selection, input, out)?;
    }
    Ok(())
}

fn main() {
    let matches = cli().get_matches();
    let opts = Opts::from_matches(&matches);

    let mut out = match open_output(&opts) {
        Ok(o) => o,
        Err(msg) => {
            let _ = io::stderr().write_all(msg.as_bytes());
            std::process::exit(1);
        }
    };

    // The delimiter regex is validated before anything else is parsed.
    if let Err(msg) = build_delimiter(&opts) {
        let _ = io::stderr().write_all(msg.as_bytes());
        std::mem::forget(out);
        std::process::exit(1);
    }

    match run(&opts, &mut out) {
        Ok(()) => {
            // Flushing happens on drop; errors are ignored.
            drop(out);
        }
        Err(Fatal::BrokenPipe) => {
            std::mem::forget(out);
            std::process::exit(0);
        }
        Err(Fatal::Logged(msg)) => {
            diag::error(&msg);
            std::mem::forget(out);
            std::process::exit(1);
        }
        Err(Fatal::Panic(loc, msg)) => {
            diag::panic_message(loc, &msg);
            drop(out);
            std::process::exit(diag::PANIC_EXIT_CODE);
        }
    }
}
