If a file has a recognizable file extension indicating that it is compressed, and a local binary to perform decompression is found, decompression will occur automagically. This requires with `-z`.";

const HEADER_STDIN_PANIC_LOCATION: &str = "/workspace/src/lib/core.rs:94:21";
const HEADER_STDIN_PANIC_MESSAGE: &str =
    "not implemented: Header selections not supported when piping gzipped stdin";
const HEADER_STDIN_WARNING: &str =
    "Selections based on header fields is not currently supported on STDIN compressed data.";

fn parse_regex(s: &str) -> Result<Regex, String> {
    Regex::new(s).map_err(|e| e.to_string())
}

fn cli() -> Command {
    Command::new("hck")
        .version("git:0e2b6ba")
        .about(ABOUT)
        .long_about(format!("{}\n\n{}", ABOUT, LONG_ABOUT_TAIL))
        .arg(
            Arg::new("input")
                .value_name("INPUT")
                .num_args(0..)
                .action(ArgAction::Append)
                .help(INPUT_HELP)
                .long_help(INPUT_LONG_HELP),
        )
        .arg(
            Arg::new("output")
                .short('o')
                .long("output")
                .value_name("OUTPUT")
                .allow_hyphen_values(true)
                .help("Output file to write to, defaults to stdout"),
        )
        .arg(
            Arg::new("delimiter")
                .short('d')
                .long("delimiter")
                .value_name("DELIMITER")
                .default_value("\\s+")
                .allow_hyphen_values(true)
                .help("Delimiter to use on input files, this is a substring literal by default. To treat it as a literal add the `-L` flag"),
        )
        .arg(
            Arg::new("delim_is_literal")
                .short('L')
                .long("delim-is-literal")
                .action(ArgAction::SetTrue)
                .help("Treat the delimiter as a string literal. This can significantly improve performance, especially for single byte delimiters"),
        )
        .arg(
            Arg::new("use_input_delim")
                .short('I')
                .long("use-input-delim")
                .action(ArgAction::SetTrue)
                .help("Use the input delimiter as the output delimiter if the input is literal and no other output delimiter has been set"),
        )
        .arg(
            Arg::new("output_delimiter")
                .short('D')
                .long("output-delimiter")
                .value_name("OUTPUT_DELIMITER")
                .default_value("\t")
                .allow_hyphen_values(true)
                .help("Delimiter string to use on outputs"),
        )
        .arg(
            Arg::new("fields")
                .short('f')
                .long("fields")
                .value_name("FIELDS")
                .allow_hyphen_values(true)
                .help("Fields to keep in the output, ex: 1,2-,-5,2-5. Fields are 1-based and inclusive"),
        )
        .arg(
            Arg::new("exclude")
                .short('e')
                .long("exclude")
                .value_name("EXCLUDE")
                .allow_hyphen_values(true)
                .help("Fields to exclude from the output, ex: 3,9-11,15-. Exclude fields are 1 based and inclusive. Exclude fields take precedence over `fields`"),
        )
        .arg(
            Arg::new("exclude_header")
                .short('E')
                .long("exclude-header")
                .value_name("EXCLUDE_HEADER")
                .action(ArgAction::Append)
                .allow_hyphen_values(true)
                .value_parser(parse_regex)
                .help("Headers to exclude from the output, ex: '^badfield.*$`. This is a string literal by default. Add the `-r` flag to treat as a regex"),
        )
        .arg(
            Arg::new("header_field")
                .short('F')
                .long("header-field")
                .value_name("HEADER_FIELD")
                .action(ArgAction::Append)
                .allow_hyphen_values(true)
                .value_parser(parse_regex)
                .help("A string literal or regex to select headers, ex: '^is_.*$`. This is a string literal by default. add the `-r` flag to treat it as a regex"),
        )
        .arg(
            Arg::new("header_is_regex")
                .short('r')
                .long("header-is-regex")
                .action(ArgAction::SetTrue)
                .help("Treat the header_fields as regexs instead of string literals"),
        )
        .arg(
            Arg::new("try_decompress")
                .short('z')
                .long("try-decompress")
                .action(ArgAction::SetTrue)
                .help("Try to find the correct decompression method based on the file extensions"),
        )
        .arg(
            Arg::new("try_compress")
                .short('Z')
                .long("try-compress")
                .action(ArgAction::SetTrue)
                .help("Try to gzip compress the output"),
        )
        .arg(
            Arg::new("compression_threads")
                .short('t')
                .long("compression-threads")
                .value_name("COMPRESSION_THREADS")
                .default_value("4")
                .value_parser(clap::value_parser!(usize))
                .help("Threads to use for compression, 0 will result in `hck` staying single threaded"),
        )
        .arg(
            Arg::new("compression_level")
                .short('l')
                .long("compression-level")
                .value_name("COMPRESSION_LEVEL")
                .default_value("6")
                .value_parser(clap::value_parser!(u32))
                .help("Compression level"),
        )
        .arg(
            Arg::new("no_mmap")
                .long("no-mmap")
                .action(ArgAction::SetTrue)
                .help("Disallow the possibility of using mmap"),
        )
        .arg(
            Arg::new("crlf")
                .long("crlf")
                .action(ArgAction::SetTrue)
                .help("Support CRLF newlines"),
        )
}

/// Settings derived from the command line.
struct Opts {
    inputs: Vec<Input>,
    output: Option<String>,
    delimiter: String,
    delim_is_literal: bool,
    use_input_delim: bool,
    output_delimiter: String,
    fields: Option<String>,
    exclude: Option<String>,
    exclude_header: Vec<Regex>,
    header_field: Vec<Regex>,
    header_is_regex: bool,
    try_decompress: bool,
    try_compress: bool,
    compression_level: u32,
    no_mmap: bool,
    crlf: bool,
}

impl Opts {
    fn from_matches(m: &clap::ArgMatches) -> Opts {
        let inputs: Vec<Input> = m
            .get_many::<String>("input")
            .map(|v| v.map(|s| Input::from_arg(s)).collect())
            .unwrap_or_default();
        Opts {
            inputs,
            output: m.get_one::<String>("output").cloned(),
            delimiter: m.get_one::<String>("delimiter").cloned().unwrap_or_default(),
            delim_is_literal: m.get_flag("delim_is_literal"),
            use_input_delim: m.get_flag("use_input_delim"),
            output_delimiter: m.get_one::<String>("output_delimiter").cloned().unwrap_or_default(),
            fields: m.get_one::<String>("fields").cloned(),
            exclude: m.get_one::<String>("exclude").cloned(),
            exclude_header: m
                .get_many::<Regex>("exclude_header")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
            header_field: m
                .get_many::<Regex>("header_field")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
            header_is_regex: m.get_flag("header_is_regex"),
            try_decompress: m.get_flag("try_decompress"),
            try_compress: m.get_flag("try_compress"),
            compression_level: *m.get_one::<u32>("compression_level").unwrap_or(&6),
            no_mmap: m.get_flag("no_mmap"),
            crlf: m.get_flag("crlf"),
        }
    }

    fn header_mode(&self) -> bool {
        !self.header_field.is_empty() || !self.exclude_header.is_empty()
    }
}

/// Fatal conditions.
enum Fatal {
    /// Logged as an error, exit code 1, buffered output discarded.
    Logged(String),
    /// Reported like a panic, exit code 101, buffered output flushed.
    Panic(&'static str, String),
    /// A broken pipe on output: silently exit with success.
    BrokenPipe,
}

impl From<io::Error> for Fatal {
    fn from(e: io::Error) -> Fatal {
        if e.kind() == io::ErrorKind::BrokenPipe {
            Fatal::BrokenPipe
        } else {
            Fatal::Logged(e.to_string())
        }
    }
}

impl From<ProcessError> for Fatal {
    fn from(e: ProcessError) -> Fatal {
        match e {
            ProcessError::Io(e) => e.into(),
            ProcessError::Panic(loc, msg) => Fatal::Panic(loc, msg),
        }
    }
}

impl From<FieldError> for Fatal {
    fn from(e: FieldError) -> Fatal {
        Fatal::Logged(e.to_string())
    }
}

type Sink = BufWriter<BufWriter<Box<dyn Write>>>;

fn open_output(opts: &Opts) -> Result<Sink, String> {
    let raw: Box<dyn Write> = match &opts.output {
        Some(path) if path != "-" => match File::create(path) {
            Ok(f) => Box::new(f),
            Err(e) => {
                return Err(format!(
                    "Error: Failed to open {} for writing.\n\nCaused by:\n    {}\n",
                    path, e
                ))
            }
        },
        _ => Box::new(io::stdout()),
    };
    let sink: Box<dyn Write> = if opts.try_compress {
        Box::new(output::BgzfWriter::new(raw, opts.compression_level))
    } else {
        raw
    };
    Ok(BufWriter::with_capacity(8192, BufWriter::with_capacity(8192, sink)))
}

/// The static (header independent) part of the field selection.
struct Selection {
    fields: Option<Vec<FieldRange>>,
    excludes: Vec<FieldRange>,
}

impl Selection {
    /// Ranges to use when no header based selection applies.
    fn plain_ranges(&self) -> Vec<FieldRange> {
        let base = match &self.fields {
            Some(f) => f.clone(),
            None => vec![FieldRange { low: 0, high: usize::MAX - 1, pos: 0 }],
        };
        FieldRange::exclude(base, &self.excludes)
    }

    /// Ranges for a specific header line.
    fn header_ranges(&self, opts: &Opts, header: &[u8], delim: &Delimiter) -> Result<Vec<FieldRange>, FieldError> {
        let header_fields = delim.split(header);
        let mut selected = self.fields.clone().unwrap_or_default();
        if !opts.header_field.is_empty() {
            let by_header = FieldRange::from_header_list(&opts.header_field, &header_fields, opts.header_is_regex);
            if by_header.is_empty() {
                return Err(FieldError::NoHeadersMatched);
            }
            selected = FieldRange::combine(selected, by_header);
        } else if self.fields.is_none() {
            selected = vec![FieldRange { low: 0, high: usize::MAX - 1, pos: 0 }];
        }
        let mut excludes = self.excludes.clone();
        if !opts.exclude_header.is_empty() {
            excludes.extend(FieldRange::from_header_list(
                &opts.exclude_header,
                &header_fields,
                opts.header_is_regex,
            ));
        }
        Ok(FieldRange::exclude(selected, &excludes))
    }
}

fn build_delimiter(opts: &Opts) -> Result<Delimiter, String> {
    if opts.delim_is_literal {
        Ok(Delimiter::literal(unescape::unescape(&opts.delimiter)))
    } else {
        match Regex::new(&opts.delimiter) {
            Ok(re) => Ok(Delimiter::Regex(re)),
            Err(e) => Err(format!("Error: {}\n", e)),
        }
    }
}

fn output_delimiter(opts: &Opts) -> Vec<u8> {
    if opts.delim_is_literal && opts.use_input_delim {
        unescape::unescape(&opts.delimiter)
    } else {
        unescape::unescape(&opts.output_delimiter)
    }
}

/// Read a single line (including its terminator, if any) from a stream.
fn read_header_line<R: Read>(reader: &mut R) -> io::Result<Vec<u8>> {
    let mut buf = Vec::new();
    let mut byte = [0u8; 1];
    loop {
        let n = reader.read(&mut byte)?;
        if n == 0 {
            break;
        }
        buf.push(byte[0]);
        if byte[0] == b'\n' {
            break;
        }
    }
    Ok(buf)
}

fn strip_line_end(mut line: &[u8], crlf: bool) -> &[u8] {
    if let [rest @ .., b'\n'] = line {
        line = rest;
    }
    if crlf {
        if let [rest @ .., b'\r'] = line {
            line = rest;
        }
    }
    line
}

fn process_input(opts: &Opts, selection: &Selection, input: &Input, out: &mut Sink) -> Result<(), Fatal> {
    let delim = build_delimiter(opts).map_err(Fatal::Logged)?;
    let out_delim = output_delimiter(opts);
    let allow_whole = !opts.no_mmap && !opts.try_decompress;

    if !opts.header_mode() {
        let ranges = selection.plain_ranges();
        if ranges.is_empty() {
            return Ok(());
        }
        let mut core = Core::new(ranges, delim, out_delim, opts.crlf);
        return match input::open(input, opts.try_decompress, allow_whole)? {
            Opened::Whole(data) => Ok(process_whole(&data, &mut core, out)?),
            Opened::Stream(mut reader) => Ok(process_stream(&mut *reader, &mut core, out)?),
        };
    }

    if input.is_stdin() {
        if opts.try_decompress {
            if !opts.header_field.is_empty() {
                diag::warn(HEADER_STDIN_WARNING);
            }
            return Err(Fatal::Panic(HEADER_STDIN_PANIC_LOCATION, HEADER_STDIN_PANIC_MESSAGE.to_string()));
        }
        let mut reader = match input::open(input, false, false)? {
            Opened::Stream(r) => r,
            Opened::Whole(_) => unreachable!(),
        };
        let header_line = read_header_line(&mut reader)?;
        let header = strip_line_end(&header_line, opts.crlf);
        let ranges = selection.header_ranges(opts, header, &delim)?;
        if ranges.is_empty() {
            return Ok(());
        }
        let mut core = Core::new(ranges, delim, out_delim, opts.crlf);
        core.write_line(header, out)?;
        process_stream(&mut *reader, &mut core, out)?;
        return Ok(());
    }

    // Files: the header is read through a separate handle, then the whole
    // input (header included) is processed.
    let header_line = match input::open(input, opts.try_decompress, false)? {
        Opened::Stream(mut r) => {
            let mut br = BufReader::new(&mut *r);
            let mut line = Vec::new();
            br.read_until(b'\n', &mut line)?;
            line
        }
        Opened::Whole(data) => {
            let end = memchr::memchr(b'\n', &data).map(|i| i + 1).unwrap_or(data.len());
            data[..end].to_vec()
        }
    };
    let header = strip_line_end(&header_line, opts.crlf);
    let ranges = selection.header_ranges(opts, header, &delim)?;
    if ranges.is_empty() {
        return Ok(());
    }
    let mut core = Core::new(ranges, delim, out_delim, opts.crlf);
    match input::open(input, opts.try_decompress, allow_whole)? {
        Opened::Whole(data) => process_whole(&data, &mut core, out)?,
        Opened::Stream(mut reader) => process_stream(&mut *reader, &mut core, out)?,
    }
    Ok(())
}

fn run(opts: &Opts, out: &mut Sink) -> Result<(), Fatal> {
    // validate the delimiter early
    build_delimiter(opts).map_err(Fatal::Logged)?;
    let fields = match &opts.fields {
        Some(f) => Some(FieldRange::from_list(f)?),
        None => None,
    };
    let excludes = match &opts.exclude {
        Some(e) => FieldRange::from_list(e)?,
        None => Vec::new(),
    };
    let selection = Selection { fields, excludes };

    if !opts.header_mode() && selection.plain_ranges().is_empty() {
        return Ok(());
    }

    let inputs: Vec<Input> = if opts.inputs.is_empty() {
        vec![Input::Stdin]
    } else {
        opts.inputs.clone()
    };
    for input in &inputs {
        process_input(opts, &selection, input, out)?;
    }
    Ok(())
}

fn main() {
    let matches = cli().get_matches();
    let opts = Opts::from_matches(&matches);

    let mut out = match open_output(&opts) {
        Ok(o) => o,
        Err(msg) => {
            let _ = io::stderr().write_all(msg.as_bytes());
            std::process::exit(1);
        }
    };

    // The delimiter regex is validated before anything else is parsed.
    if let Err(msg) = build_delimiter(&opts) {
        let _ = io::stderr().write_all(msg.as_bytes());
        std::mem::forget(out);
        std::process::exit(1);
    }

    match run(&opts, &mut out) {
        Ok(()) => {
            // Flushing happens on drop; errors are ignored.
            drop(out);
        }
        Err(Fatal::BrokenPipe) => {
            std::mem::forget(out);
            std::process::exit(0);
        }
        Err(Fatal::Logged(msg)) => {
            diag::error(&msg);
            std::mem::forget(out);
            std::process::exit(1);
        }
        Err(Fatal::Panic(loc, msg)) => {
            diag::panic_message(loc, &msg);
            drop(out);
            std::process::exit(diag::PANIC_EXIT_CODE);
        }
    }
}
