MAX = 10**9
FIELDS = list('abcdefgh')
def parse(spec):
    out = []
    for i, item in enumerate(spec.split(',')):
        if '-' in item:
            a, b = item.split('-', 1)
            lo = int(a) if a else 1
            hi = int(b) if b else MAX
        else: lo = hi = int(item)
        out.append([lo, hi, i])
    return out

