    slots = [[] for _ in range(nslots)]
    for lo, hi, pos in ranges:
        for f in range(lo, min(hi, 8) + 1):
            slots[pos].append(FIELDS[f-1])
    return ' '.join(x for s in slots for x in s)

def render_pointer(ranges):
    slots = {}
    it = 0
    for idx in range(1, 9):
        while it < len(ranges) and idx > ranges[it][1]: it += 1
        if it == len(ranges): break
        if idx >= ranges[it][0]: slots.setdefault(ranges[it][2], []).append(FIELDS[idx-1])
    return ' '.join(x for p in sorted(slots) for x in slots[p])

