    for i in range(n):
        if i >= len(r): break
        j = i + 1
        last = r[i][2]
        merged_here = 0
        while j < len(r):
            if adjmode == 'adj': ok = r[j][0] <= r[i][1] + 1
            else: ok = r[j][0] <= r[i][1]
            if not ok: break
            if mergecond == 'p1': c = r[j][2] == r[i][2] + 1
            elif mergecond == 'chain': c = r[j][2] == last + 1
            elif mergecond == 'gt': c = r[j][2] > r[i][2]
            elif mergecond == 'any': c = True
            elif mergecond == 'ge': c = r[j][2] >= r[i][2]
            cost_ok = True
            if budget == 'total2': cost_ok = total < 2
            elif budget == 'head2': cost_ok = merged_here < 2
            elif budget == 'cost2':
                cost = 2 if r[j][0] <= r[i][1] else 1
                cost_ok = total + cost <= 2
            if c and cost_ok:
