                elif highupd == 'j': r[i][1] = b[1]
                elif highupd == 'next': r[i][1] = r[j][1] if j < len(r) else r[i][1]
                last = b[2]
            else:
                if elseact == 'break': break
                elif elseact == 'skip': j += 1
                elif elseact == 'high_j_skip':
                    if r[j][0] <= r[i][1]: r[i][1] = r[j][1]
                    j += 1
                elif elseact == 'high_j_skip_ov':
                    if r[j][0] <= r[i][1]:
                        r[i][1] = r[j][1]; j += 1
                    else: break
                elif elseact == 'highmax_skip':
                    r[i][1] = max(r[i][1], r[j][1]); j += 1
    return r

results = []
for adjmode in ['adj', 'ov']:
  for mergecond in ['p1', 'chain', 'gt', 'any', 'ge']:
    for highupd in ['max', 'j', 'next']:
      for elseact in ['break', 'skip', 'high_j_skip', 'high_j_skip_ov', 'highmax_skip']:
        for budget in ['none', 'total2', 'head2', 'cost2']:
          for rend in ['ra', 'ptr']:
