import sys; sys.path.insert(0, '/tmp')
from h5lib import *
exec(open('/tmp/h12m.py').read().split("for budget in")[0])

def general2(r, budget, cond, dec):
    r = [list(x) for x in sorted(r, key=lambda x: (x[0], x[1], x[2]))]
