        if r[i+1][0] <= r[i][1] + 1:
            b = r.pop(i+1); r[i][1] = max(r[i][1], b[1]); break
        i += 1
    return r

def render_trunc(r, nh):
    if not r: return ''
    lastu = r[-1][1]
    nfields = min(nh, lastu)
    out = []
    for lo, hi, pos, *_ in r:
        for f in range(lo, min(hi, nfields) + 1): out.append('h%d' % f)
